CREATE OR REPLACE FUNCTION "private"."events_activity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  verb text;
begin
  if tg_op = 'INSERT' then
    verb := 'event.created';
  elsif new.status = 'scheduled'
        and (old.status <> 'scheduled' or new.starts_at is distinct from old.starts_at) then
    verb := 'event.scheduled';
  elsif new.status = 'cancelled' and old.status <> 'cancelled' then
    verb := 'event.cancelled';
  else
    return null;
  end if;

  perform private.log_activity(new.group_id, coalesce(auth.uid(), new.created_by), verb, new.id,
    jsonb_build_object('title', new.title, 'emoji', new.emoji, 'starts_at', new.starts_at));
  return null;
end;
$$;


