CREATE OR REPLACE FUNCTION "private"."fx_rate"("from_currency" character, "to_currency" character, "on_day" "date" DEFAULT CURRENT_DATE) RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result numeric;
begin
  if from_currency = to_currency then
    return 1;
  end if;

  select r.rate into result
  from public.fx_rates r
  where r.base = from_currency and r.quote = to_currency and r.day <= on_day
  order by r.day desc
  limit 1;

  if result is null then
    select round(1 / r.rate, 12) into result
    from public.fx_rates r
    where r.base = to_currency and r.quote = from_currency and r.day <= on_day
    order by r.day desc
    limit 1;
  end if;

  return result;
end;
$$;


