CREATE OR REPLACE FUNCTION "private"."unsubscribe_token"("uid" "uuid", "category" "text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select uid::text || '.' || category || '.' || left(
    translate(
      encode(extensions.hmac(convert_to(uid::text || '.' || category, 'UTF8'), k.secret, 'sha256'), 'base64'),
      '+/=',
      '-_'
    ),
    32
  )
  from private.signing_keys k
  where k.name = 'email_unsubscribe';
$$;


ALTER FUNCTION "private"."unsubscribe_token"("uid" "uuid", "category" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_invite"("code" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  uid uuid := private.require_user();
  inv public.group_invites;
  my_email text;
begin
  select * into inv
  from public.group_invites i
  where i.code = accept_invite.code
  for update;

  if inv.id is null then
    raise exception using message = 'invite_not_found', detail = 'This invite link is not valid', errcode = 'PT404';
  end if;

  if exists (select 1 from public.group_members m where m.group_id = inv.group_id and m.user_id = uid) then
    return inv.group_id;
  end if;

  if inv.revoked_at is not null then
    raise exception using message = 'invite_revoked', detail = 'This invite has been revoked', errcode = '23514';
  end if;
  if inv.expires_at is not null and inv.expires_at <= now() then
    raise exception using message = 'invite_expired', detail = 'This invite has expired', errcode = '23514';
  end if;
  if inv.max_uses is not null and inv.uses >= inv.max_uses then
    raise exception using message = 'invite_used_up', detail = 'This invite has been used up', errcode = '23514';
  end if;
  if inv.email is not null then
    select lower(u.email) into my_email from auth.users u where u.id = uid;
    if my_email is distinct from inv.email then
      raise exception using message = 'invite_wrong_email', detail = 'This invite was sent to a different email address', errcode = '42501';
    end if;
  end if;
  if exists (select 1 from public.groups g where g.id = inv.group_id and g.archived_at is not null) then
    raise exception using message = 'group_archived', detail = 'This group is archived', errcode = '23514';
  end if;
  if private.blocked_in_group(inv.group_id, uid) then
    raise exception using message = 'blocked', detail = 'You cannot join this group', errcode = '42501';
  end if;

  insert into public.group_members (group_id, user_id, role)
  values (inv.group_id, uid, inv.role);

  update public.group_invites i set uses = i.uses + 1 where i.id = inv.id;

  return inv.group_id;
end;
$$;


ALTER FUNCTION "public"."accept_invite"("code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."best_slots"("event_id" "uuid", "limit" integer DEFAULT 5) RETURNS TABLE("starts_at" timestamp with time zone, "ends_at" timestamp with time zone, "yes_count" integer, "maybe_count" integer, "score" numeric, "missing" "uuid"[])
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
#variable_conflict use_column
declare
  ev public.events := private.member_event($1);
  cells int := ceil(ev.duration_minutes::numeric / ev.slot_minutes)::int;
  max_rows int := least(greatest(coalesce($2, 5), 0), 100);
begin
  return query
  with members as (
    select m.user_id from public.group_members m where m.group_id = ev.group_id
  ),
  candidates as (
    select distinct a.slot_start as slot
    from public.availability a
    join members mb on mb.user_id = a.user_id
    where a.event_id = ev.id
  ),
  per_person as (
    select
      c.slot,
      mb.user_id,
      count(a.slot_start) as covered,
      coalesce(bool_and(a.level = 'yes'), false) as all_yes
    from candidates c
    cross join members mb
    cross join generate_series(0, cells - 1) as k (i)
    left join public.availability a
      on a.event_id = ev.id
     and a.user_id = mb.user_id
     and a.slot_start = c.slot + make_interval(mins => k.i * ev.slot_minutes)
    group by c.slot, mb.user_id
  ),
  scored as (
    select
      p.slot,
      (count(*) filter (where p.covered = cells and p.all_yes))::int as yes_n,
      (count(*) filter (where p.covered = cells and not p.all_yes))::int as maybe_n,
      coalesce(array_agg(p.user_id order by p.user_id) filter (where p.covered < cells), '{}') as missing_ids
    from per_person p
    group by p.slot
  )
  select
    s.slot,
    s.slot + make_interval(mins => ev.duration_minutes),
    s.yes_n,
    s.maybe_n,
    (s.yes_n + 0.5 * s.maybe_n)::numeric,
    s.missing_ids
  from scored s
  where s.yes_n + s.maybe_n >= ev.min_attendees
  order by (s.yes_n + 0.5 * s.maybe_n) desc, s.slot asc
  limit max_rows;
end;
$_$;


ALTER FUNCTION "public"."best_slots"("event_id" "uuid", "limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calendar_feed_token"("rotate" boolean DEFAULT false) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  uid uuid := auth.uid();
  result text;
begin
  if uid is null then
    raise exception using message = 'not_authenticated', detail = 'You need to be signed in', errcode = '42501';
  end if;

  if rotate then
    delete from public.calendar_feed_tokens t where t.user_id = uid;
  end if;

  insert into public.calendar_feed_tokens (user_id, token)
  values (uid, private.random_code(24))
  on conflict (user_id) do nothing;

  select t.token into result from public.calendar_feed_tokens t where t.user_id = uid;
  return result;
end;
$$;


ALTER FUNCTION "public"."calendar_feed_token"("rotate" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_event"("event_id" "uuid") RETURNS "public"."events"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  ev public.events := private.manageable_event(cancel_event.event_id);
begin
  if ev.status = 'cancelled' then
    return ev;
  end if;
  if ev.status = 'done' then
    raise exception using message = 'event_done', detail = 'This event already happened', errcode = '23514';
  end if;

  update public.events e set status = 'cancelled'
  where e.id = ev.id
  returning * into ev;

  return ev;
end;
$$;


ALTER FUNCTION "public"."cancel_event"("event_id" "uuid") OWNER TO "postgres";


