    "currency" character(3) NOT NULL,
    "fx_rate" numeric(24,12) DEFAULT 1 NOT NULL,
    "note" "text",
    "settled_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid" DEFAULT "auth"."uid"(),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    CONSTRAINT "settlements_amount_cents_check" CHECK ((("amount_cents" > 0) AND ("amount_cents" <= '100000000000'::bigint))),
    CONSTRAINT "settlements_check" CHECK (("from_user" <> "to_user")),
    CONSTRAINT "settlements_currency_check" CHECK (("currency" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "settlements_fx_rate_check" CHECK (("fx_rate" > (0)::numeric)),
    CONSTRAINT "settlements_note_check" CHECK (("char_length"("note") <= 500))
);


