CREATE OR REPLACE FUNCTION "public"."delete_settlement"("id" "uuid") RETURNS "public"."settlements"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  s public.settlements;
  my_role public.group_role;
  uid uuid := private.require_user();
  gid uuid;
begin
  select x.group_id into gid from public.settlements x where x.id = delete_settlement.id;
  if gid is null then
    raise exception using message = 'settlement_not_found', detail = 'Payment not found', errcode = 'PT404';
  end if;
  perform 1 from public.groups g where g.id = gid for share;
  my_role := private.require_member(gid);

  select * into s from public.settlements x where x.id = delete_settlement.id for update;
  if s.id is null then
    raise exception using message = 'settlement_not_found', detail = 'Payment not found', errcode = 'PT404';
  end if;
  if my_role = 'member' and uid not in (s.from_user, s.to_user) and uid is distinct from s.created_by then
    raise exception using message = 'not_allowed', detail = 'You can only remove payments you were part of', errcode = '42501';
  end if;
  perform private.require_unarchived(s.group_id);

  if s.deleted_at is null and (
    select count(*) from public.group_members m
    where m.group_id = s.group_id and m.user_id in (s.from_user, s.to_user)
  ) <> 2 then
    raise exception using message = 'member_not_in_group', detail = 'Someone in this payment has left the group', errcode = '23514';
  end if;

  update public.settlements x set deleted_at = coalesce(x.deleted_at, now())
  where x.id = s.id
  returning * into s;
  return s;
end;
$$;


ALTER FUNCTION "public"."delete_settlement"("id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."email_outbox_report"("batch" "uuid", "delivered" boolean, "error" "text" DEFAULT NULL::"text", "rejected" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  n int;
begin
  update private.email_outbox o
  set state = 'dropped', handled_at = now(), last_error = 'rejected by notify'
  where o.batch_id = email_outbox_report.batch and o.state = 'sending'
    and o.notification_id = any (coalesce(email_outbox_report.rejected, '{}'));

  if email_outbox_report.delivered then
    update private.email_outbox o
    set state = 'sent', handled_at = now(), last_error = null
    where o.batch_id = email_outbox_report.batch and o.state = 'sending';
  else
    -- A known failure retries with a fresh batch, so a fresh idempotency key.
    update private.email_outbox o
    set state = case when o.attempts >= 5 then 'failed' else 'pending' end,
        handled_at = case when o.attempts >= 5 then now() end,
        batch_id = case when o.attempts >= 5 then o.batch_id end,
        retry_at = now() + make_interval(mins => power(2, o.attempts)::int),
        last_error = left(coalesce(email_outbox_report.error, 'send failed'), 500)
    where o.batch_id = email_outbox_report.batch and o.state = 'sending';
  end if;
  get diagnostics n = row_count;
  return n;
end;
$$;


ALTER FUNCTION "public"."email_outbox_report"("batch" "uuid", "delivered" boolean, "error" "text", "rejected" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."email_unsubscribe"("token" "text", "action" "text" DEFAULT 'unsubscribe'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  parts text[] := string_to_array(coalesce(token, ''), '.');
  uid uuid;
  cat text;
  cats text[];
  saved jsonb;
  active boolean;
  address text;
  subscribed boolean;
  restored boolean := false;
begin
  if cardinality(parts) = 3 then
    uid := private.try_uuid(parts[1]);
    cat := parts[2];
  end if;

  if uid is null
     or not (cat = 'all' or exists (
       select 1 from private.notification_categories c where c.category = cat and c.email_allowed
     ))
     or token is distinct from private.unsubscribe_token(uid, cat) then
    raise exception using message = 'invalid_unsubscribe_link', detail = 'This unsubscribe link is not valid', errcode = '22023';
  end if;
  if action is null or action not in ('preview', 'unsubscribe', 'undo') then
    raise exception using message = 'invalid_payload', detail = 'action must be preview, unsubscribe or undo', errcode = '22023';
  end if;

  select array_agg(c.category order by c.position) into cats
  from private.notification_categories c
  where c.email_allowed and (cat = 'all' or c.category = cat);

  active := exists (select 1 from public.profiles p where p.id = uid and p.deleted_at is null);

  if active and action = 'unsubscribe' then
    -- Only the first click is remembered: a second one would snapshot "all off".
    insert into private.email_unsubscribe_undo (user_id, scope, prior)
    select uid, cat, jsonb_object_agg(s.c, p.email)
    from unnest(cats) as s (c)
    join private.notification_categories c on c.category = s.c
    left join public.notification_prefs p on p.user_id = uid and p.category = s.c
    having bool_or(coalesce(p.email, c.email_default))
    on conflict (user_id, scope) do nothing;

    insert into public.notification_prefs as p (user_id, category, email)
    select uid, s.c, false from unnest(cats) as s (c)
    on conflict (user_id, category) do update set email = false;
  elsif active and action = 'undo' then
    delete from private.email_unsubscribe_undo u
    where u.user_id = uid and u.scope = cat
    returning u.prior into saved;

    -- With the snapshot: exactly what it held. Without one (already undone, or the
    -- person changed settings since): a one-category link turns that email on; an
    -- 'all' link changes nothing, since there is nothing to put back.
    if saved is not null or cat <> 'all' then
      insert into public.notification_prefs as p (user_id, category, email)
      select uid, s.c, case when saved is not null then (saved ->> s.c)::boolean else true end
      from unnest(cats) as s (c)
      on conflict (user_id, category) do update set email = excluded.email;
      restored := true;
    end if;
  end if;

  select bool_or(coalesce(p.email, c.email_default)) into subscribed
  from unnest(cats) as s (c)
  join private.notification_categories c on c.category = s.c
  left join public.notification_prefs p on p.user_id = uid and p.category = s.c;

  if active then
    select u.email into address from auth.users u where u.id = uid;
  end if;

  return jsonb_build_object(
    'category', cat,
    'email', private.mask_email(address),
    'subscribed', active and coalesce(subscribed, false),
    'restored', restored
  );
end;
$$;


ALTER FUNCTION "public"."email_unsubscribe"("token" "text", "action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_or_create_direct_group"("friend_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  uid uuid := private.require_user();
  gid uuid;
begin
  if get_or_create_direct_group.friend_id = uid then
    raise exception using message = 'invalid_friend', detail = 'You cannot split with yourself', errcode = '22023';
  end if;

  if not exists (
    select 1 from public.profiles p
    where p.id = get_or_create_direct_group.friend_id
      and p.deleted_at is null
      and p.id in (select private.my_contact_ids())
  ) then
    raise exception using message = 'not_a_friend', detail = 'You can only split with friends', errcode = '42501';
  end if;

  if private.has_block(uid, get_or_create_direct_group.friend_id) then
    raise exception using message = 'blocked', detail = 'You cannot split with this person', errcode = '42501';
  end if;

  -- Serialize creation per pair so two taps do not create two groups.
  perform pg_advisory_xact_lock(hashtextextended(
    least(uid::text, get_or_create_direct_group.friend_id::text)
      || greatest(uid::text, get_or_create_direct_group.friend_id::text),
    0
  ));

  select g.id into gid
  from public.groups g
  where g.is_direct
    and exists (select 1 from public.group_members m where m.group_id = g.id and m.user_id = uid)
    and exists (
      select 1 from public.group_members m
      where m.group_id = g.id and m.user_id = get_or_create_direct_group.friend_id
    )
  order by g.created_at
  limit 1;

  if gid is not null then
    return gid;
  end if;

  insert into public.groups (name, currency, is_direct, members_can_invite, created_by)
  select 'Direct', p.default_currency, true, false, uid
  from public.profiles p where p.id = uid
  returning id into gid;

  insert into public.group_members (group_id, user_id, role)
  values (gid, uid, 'owner'), (gid, get_or_create_direct_group.friend_id, 'admin');

  return gid;
end;
$$;


ALTER FUNCTION "public"."get_or_create_direct_group"("friend_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."invite_preview"("code" "text") RETURNS TABLE("group_id" "uuid", "name" "text", "emoji" "text", "color" "text", "cover_path" "text", "member_count" integer, "first_names" "text"[], "status" "text", "is_member" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  inv public.group_invites;
  uid uuid := auth.uid();
begin
  select * into inv from public.group_invites i where i.code = invite_preview.code;

  if inv.id is null then
    raise exception using message = 'invite_not_found', detail = 'This invite link is not valid', errcode = 'PT404';
  end if;

  return query
  select
    g.id,
    g.name,
    g.emoji,
    g.color,
    g.cover_path,
    (select count(*)::int from public.group_members m where m.group_id = g.id),
    array(
      select split_part(p.display_name, ' ', 1)
      from public.group_members m
      join public.profiles p on p.id = m.user_id
      where m.group_id = g.id and p.deleted_at is null
      order by (m.role = 'owner') desc, m.joined_at, p.id
      limit 5
    ),
    case
      when inv.revoked_at is not null then 'revoked'
      when inv.expires_at is not null and inv.expires_at <= now() then 'expired'
      when inv.max_uses is not null and inv.uses >= inv.max_uses then 'used_up'
      when g.archived_at is not null then 'archived'
      when uid is not null and not x.is_member and private.blocked_in_group(g.id, uid) then 'blocked'
      else 'valid'
    end,
    x.is_member
  from public.groups g
  cross join lateral (
    select exists (
      select 1 from public.group_members m
      where m.group_id = g.id and m.user_id = uid
    ) as is_member
  ) x
  where g.id = inv.group_id;
end;
$$;


ALTER FUNCTION "public"."invite_preview"("code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."leave_group"("group_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  my_role public.group_role;
  uid uuid := auth.uid();
  others_active int;
begin
  perform 1 from public.groups g where g.id = leave_group.group_id for no key update;
  my_role := private.require_member(leave_group.group_id);

  select count(*) into others_active
  from public.group_members m
  join public.profiles p on p.id = m.user_id
  where m.group_id = leave_group.group_id and m.user_id <> uid and p.deleted_at is null;

  if my_role = 'owner' and others_active = 0 then
    if exists (
      select 1 from public.group_balances b
      join public.profiles p on p.id = b.user_id
      where b.group_id = leave_group.group_id
        and b.user_id <> uid
        and p.deleted_at is null
        and b.net_cents <> 0
    ) then
      raise exception using message = 'member_has_balance', detail = 'Someone here still has an unsettled balance', errcode = '23514';
    end if;
    -- Whatever is left is between the owner and closed accounts, which nobody
    -- can settle anymore; the delete guard allows this like closing an account.
    perform set_config('potluck.closing_account', 'on', true);
    delete from public.groups g where g.id = leave_group.group_id;
    perform set_config('potluck.closing_account', '', true);
    return;
  end if;

  if private.member_balance(leave_group.group_id, uid) <> 0 then
    raise exception using message = 'member_has_balance', detail = 'Settle up before leaving this group', errcode = '23514';
  end if;

  if my_role = 'owner' then
    raise exception using message = 'owner_must_transfer', detail = 'Transfer ownership before leaving', errcode = '23514';
  end if;

  delete from public.group_members m
  where m.group_id = leave_group.group_id and m.user_id = uid;
end;
$$;


ALTER FUNCTION "public"."leave_group"("group_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."my_notification_prefs"() RETURNS TABLE("category" "text", "push" boolean, "email" boolean, "push_allowed" boolean, "email_allowed" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  uid uuid := private.require_user();
begin
  return query
  select
    c.category,
    c.push_allowed and coalesce(p.push, c.push_default),
    c.email_allowed and coalesce(p.email, c.email_default),
    c.push_allowed,
    c.email_allowed
  from private.notification_categories c
  left join public.notification_prefs p on p.user_id = uid and p.category = c.category
  order by c.position;
end;
$$;


ALTER FUNCTION "public"."my_notification_prefs"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."my_timeline"("from" timestamp with time zone DEFAULT "now"(), "to" timestamp with time zone DEFAULT ("now"() + '60 days'::interval)) RETURNS TABLE("event_id" "uuid", "group_id" "uuid", "group_name" "text", "group_emoji" "text", "group_color" "text", "title" "text", "emoji" "text", "location" "text", "status" "public"."event_status", "timezone" "text", "starts_at" timestamp with time zone, "ends_at" timestamp with time zone, "window_start" "date", "window_end" "date", "rsvp_deadline" timestamp with time zone, "my_rsvp" "public"."rsvp_status", "going_count" integer, "availability_requested" boolean, "availability_submitted" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
#variable_conflict use_column
declare
  uid uuid := private.require_user();
  range_from timestamptz := coalesce($1, now());
  range_to timestamptz := coalesce($2, now() + interval '60 days');
begin
  return query
  select
    e.id,
    g.id,
    g.name,
    g.emoji,
    g.color,
    e.title,
    e.emoji,
    e.location,
    e.status,
    e.timezone,
    e.starts_at,
    e.ends_at,
    e.window_start,
    e.window_end,
    e.rsvp_deadline,
    r.status,
    (select count(*)::int from public.event_rsvps x where x.event_id = e.id and x.status = 'going'),
    exists (
      select 1 from public.availability_requests q
      where q.event_id = e.id and q.user_id = uid and q.responded_at is null
    ),
    exists (select 1 from public.availability a where a.event_id = e.id and a.user_id = uid)
  from public.events e
  join public.group_members m on m.group_id = e.group_id and m.user_id = uid
  join public.groups g on g.id = e.group_id
  left join public.event_rsvps r on r.event_id = e.id and r.user_id = uid
  where
    (e.status = 'scheduled' and e.starts_at < range_to and coalesce(e.ends_at, e.starts_at) >= range_from)
    or (
      e.status = 'polling'
      and e.window_end >= (range_from at time zone e.timezone)::date
      and e.window_start <= (range_to at time zone e.timezone)::date
    )
  order by coalesce(e.starts_at, (e.window_start::timestamp at time zone e.timezone)), e.id;
end;
$_$;


ALTER FUNCTION "public"."my_timeline"("from" timestamp with time zone, "to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_member"("group_id" "uuid", "user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  my_role public.group_role;
  target_role public.group_role;
begin
  -- Waits for money writes in flight; new ones wait for this transaction.
  -- Membership is read once the lock is held, so a caller removed meanwhile is refused.
  perform 1 from public.groups g where g.id = remove_member.group_id for no key update;
  my_role := private.require_member(remove_member.group_id);

  if remove_member.user_id = auth.uid() then
    raise exception using message = 'use_leave_group', detail = 'Use leave group to remove yourself', errcode = '22023';
  end if;
  if my_role = 'member' then
    raise exception using message = 'not_allowed', detail = 'Only owners and admins can remove members', errcode = '42501';
  end if;

  select m.role into target_role
  from public.group_members m
  where m.group_id = remove_member.group_id and m.user_id = remove_member.user_id;

  if target_role is null then
    raise exception using message = 'member_not_found', detail = 'That person is not in this group', errcode = 'PT404';
  end if;
  if target_role = 'owner' then
    raise exception using message = 'cannot_remove_owner', detail = 'The owner cannot be removed', errcode = '42501';
  end if;
  if my_role = 'admin' and target_role <> 'member' then
    raise exception using message = 'not_allowed', detail = 'Admins can only manage regular members', errcode = '42501';
  end if;
  if private.member_balance(remove_member.group_id, remove_member.user_id) <> 0 then
    raise exception using message = 'member_has_balance', detail = 'This member still has an unsettled balance', errcode = '23514';
  end if;

  delete from public.group_members m
  where m.group_id = remove_member.group_id and m.user_id = remove_member.user_id;
end;
$$;


ALTER FUNCTION "public"."remove_member"("group_id" "uuid", "user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_availability"("event_id" "uuid", "user_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  uid uuid := private.require_user();
  ev public.events := private.member_event(request_availability.event_id);
  targets uuid[];
begin
  perform private.require_group_open(ev.group_id);
  if ev.status <> 'polling' then
    raise exception using message = 'event_not_polling', detail = 'This event is no longer collecting availability', errcode = '23514';
  end if;

  if user_ids is null or cardinality(user_ids) = 0 then
    select coalesce(array_agg(m.user_id order by m.user_id), '{}') into targets
    from public.group_members m
    join public.profiles p on p.id = m.user_id
    where m.group_id = ev.group_id
      and m.user_id <> uid
      and p.deleted_at is null
      and not exists (select 1 from public.availability a where a.event_id = ev.id and a.user_id = m.user_id);
  else
    if exists (
      select 1 from unnest(user_ids) as t (id)
      where not exists (select 1 from public.group_members m where m.group_id = ev.group_id and m.user_id = t.id)
    ) then
      raise exception using message = 'member_not_found', detail = 'Everyone asked must be in the group', errcode = 'PT404';
    end if;
    select coalesce(array_agg(distinct t.id), '{}') into targets
    from unnest(user_ids) as t (id)
    join public.profiles p on p.id = t.id
    where t.id <> uid
      and p.deleted_at is null;
  end if;

  insert into public.availability_requests (event_id, user_id, requested_by, requested_at, responded_at)
  select ev.id, t.id, uid, now(), null
  from unnest(targets) as t (id)
  on conflict (event_id, user_id) do update
    set requested_by = excluded.requested_by,
        requested_at = excluded.requested_at,
        responded_at = null;

  insert into public.notifications (user_id, type, data)
  select t.id, 'availability.requested', jsonb_build_object(
    'event_id', ev.id,
    'group_id', ev.group_id,
    'event_title', ev.title,
    'actor_id', uid
  )
  from unnest(targets) as t (id);

  if cardinality(targets) > 0 then
    perform private.log_activity(ev.group_id, uid, 'availability.requested', ev.id,
      jsonb_build_object('title', ev.title, 'user_ids', to_jsonb(targets)));
  end if;

  return cardinality(targets);
end;
$$;


ALTER FUNCTION "public"."request_availability"("event_id" "uuid", "user_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_expense"("id" "uuid") RETURNS "public"."expenses"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  gid uuid := (select x.group_id from public.expenses x where x.id = restore_expense.id);
  e public.expenses;
begin
  if gid is not null then
    perform 1 from public.groups g where g.id = gid for share;
    perform private.require_member(gid);
  end if;
  e := private.editable_expense(restore_expense.id);

  if e.deleted_at is null then
    return e;
  end if;

  if exists (
    select s.user_id from public.expense_splits s where s.expense_id = e.id and s.share_cents > 0
    union
    select p.user_id from public.expense_payers p where p.expense_id = e.id
    union
    select e.paid_by
    except
    select m.user_id from public.group_members m where m.group_id = e.group_id
  ) then
    raise exception using message = 'split_member_not_in_group', detail = 'Someone in this expense has left the group', errcode = '23514';
  end if;

  update public.expenses x set deleted_at = null where x.id = e.id returning * into e;
  return e;
end;
$$;


ALTER FUNCTION "public"."restore_expense"("id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."schedule_event"("event_id" "uuid", "starts_at" timestamp with time zone) RETURNS "public"."events"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  ev public.events := private.manageable_event(schedule_event.event_id);
begin
  if schedule_event.starts_at is null then
    raise exception using message = 'starts_at_required', detail = 'Pick a start time', errcode = '22023';
  end if;
  if ev.status not in ('polling', 'scheduled') then
    raise exception using message = 'event_not_schedulable', detail = 'This event can no longer be scheduled', errcode = '23514';
  end if;

  update public.events e set
    status = 'scheduled',
    starts_at = schedule_event.starts_at,
    ends_at = schedule_event.starts_at + make_interval(mins => e.duration_minutes),
    reminder_sent_at = case
      when e.starts_at is distinct from schedule_event.starts_at then null
      else e.reminder_sent_at
    end
  where e.id = ev.id
  returning * into ev;

  return ev;
end;
$$;


ALTER FUNCTION "public"."schedule_event"("event_id" "uuid", "starts_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_availability"("event_id" "uuid", "slots" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  uid uuid := private.require_user();
  ev public.events := private.member_event(set_availability.event_id);
  parsed jsonb;
  saved int;
begin
  perform private.require_group_open(ev.group_id);
  if ev.status <> 'polling' then
    raise exception using message = 'event_not_polling', detail = 'This event is no longer collecting availability', errcode = '23514';
  end if;
  if slots is null or jsonb_typeof(slots) <> 'array' then
    raise exception using message = 'invalid_slots', detail = 'Availability is not valid', errcode = '22023';
  end if;
  if jsonb_array_length(slots) > 5000 then
    raise exception using message = 'invalid_slots', detail = 'Too many slots', errcode = '22023';
  end if;

  begin
    select coalesce(jsonb_agg(jsonb_build_object('slot_start', x.slot_start, 'level', x.level)), '[]'::jsonb)
    into parsed
    from (
      select
        (e.elem ->> 'slot_start')::timestamptz as slot_start,
        coalesce((e.elem ->> 'level')::public.availability_level, 'yes') as level
      from jsonb_array_elements(slots) as e (elem)
    ) x;
  exception
    when invalid_text_representation or invalid_datetime_format or datetime_field_overflow then
      raise exception using message = 'invalid_slots', detail = 'Availability is not valid', errcode = '22023';
  end;

  if exists (
    select 1
    from jsonb_to_recordset(parsed) as s (slot_start timestamptz, level public.availability_level)
    cross join lateral (
      select (s.slot_start at time zone ev.timezone) as local_ts
    ) l
    cross join lateral (
      select
        l.local_ts::date as day,
        (extract(hour from l.local_ts) * 60 + extract(minute from l.local_ts))::int as minute,
        extract(second from l.local_ts) as sec
    ) t
    where s.slot_start is null
       or t.day < ev.window_start
       or t.day > ev.window_end
       or t.sec <> 0
       or t.minute < ev.day_start_minute
       or t.minute + ev.slot_minutes > ev.day_end_minute
       or (t.minute - ev.day_start_minute) % ev.slot_minutes <> 0
  ) then
    raise exception using message = 'invalid_slot', detail = 'Some times are outside this event''s grid', errcode = '22023';
  end if;

  if (select count(*) from jsonb_array_elements(parsed)) <> (
    select count(distinct (s.slot_start))
    from jsonb_to_recordset(parsed) as s (slot_start timestamptz, level public.availability_level)
  ) then
    raise exception using message = 'duplicate_slot', detail = 'A time appears twice', errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(ev.id::text || ':' || uid::text, 0));

  delete from public.availability a
  where a.event_id = ev.id and a.user_id = uid;

  insert into public.availability (event_id, user_id, slot_start, level)
  select ev.id, uid, s.slot_start, s.level
  from jsonb_to_recordset(parsed) as s (slot_start timestamptz, level public.availability_level);

  get diagnostics saved = row_count;

  update public.availability_requests r
  set responded_at = now()
  where r.event_id = ev.id and r.user_id = uid;

  return saved;
end;
$$;


ALTER FUNCTION "public"."set_availability"("event_id" "uuid", "slots" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_default_split"("group_id" "uuid", "split" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  uid uuid := private.require_user();
  kind public.split_type;
  normalized jsonb;
begin
  perform private.require_member(set_default_split.group_id);
  perform private.require_group_open(set_default_split.group_id);

  if split is null or jsonb_typeof(split) = 'null' then
    update public.groups g set default_split = null where g.id = set_default_split.group_id;
    perform private.log_activity(set_default_split.group_id, uid, 'group.default_split', set_default_split.group_id,
      jsonb_build_object('split_type', null));
    return null;
  end if;

  if jsonb_typeof(split) <> 'object' or jsonb_typeof(split -> 'splits') is distinct from 'array' then
    raise exception using message = 'invalid_splits', detail = 'The split is not valid', errcode = '22023';
  end if;
  begin
    kind := (split ->> 'split_type')::public.split_type;
  exception when invalid_text_representation then
    kind := null;
  end;
  if kind is null or kind not in ('equal', 'percent', 'shares') then
    raise exception using message = 'invalid_splits', detail = 'A default split is equal, by percent or by shares', errcode = '22023';
  end if;

  -- Same validation as an expense (people, duplicates, weights, percent sum).
  select jsonb_agg(
           jsonb_build_object('user_id', c.user_id, 'weight', case when kind = 'equal' then null else c.weight end)
           order by c.user_id)
  into normalized
  from private.compute_splits(10000, kind, split -> 'splits') c;

  if exists (
    select 1 from jsonb_array_elements(normalized) e
    where not exists (
      select 1 from public.group_members m
      where m.group_id = set_default_split.group_id and m.user_id = (e ->> 'user_id')::uuid
    )
  ) then
    raise exception using message = 'split_member_not_in_group', detail = 'Everyone in the split must be in the group', errcode = '23514';
  end if;

  normalized := jsonb_build_object('split_type', kind, 'splits', normalized);
  update public.groups g set default_split = normalized where g.id = set_default_split.group_id;
  perform private.log_activity(set_default_split.group_id, uid, 'group.default_split', set_default_split.group_id,
    jsonb_build_object('split_type', kind));
  return normalized;
end;
$$;


ALTER FUNCTION "public"."set_default_split"("group_id" "uuid", "split" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_member_role"("group_id" "uuid", "user_id" "uuid", "role" "public"."group_role") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  my_role public.group_role := private.require_member(set_member_role.group_id);
  target_role public.group_role;
begin
  if my_role = 'member' then
    raise exception using message = 'not_allowed', detail = 'Only owners and admins can change roles', errcode = '42501';
  end if;
  if set_member_role.role = 'owner' then
    raise exception using message = 'use_transfer_ownership', detail = 'Use transfer ownership to make someone the owner', errcode = '22023';
  end if;

  select m.role into target_role
  from public.group_members m
  where m.group_id = set_member_role.group_id and m.user_id = set_member_role.user_id;

  if target_role is null then
    raise exception using message = 'member_not_found', detail = 'That person is not in this group', errcode = 'PT404';
  end if;
  if target_role = 'owner' then
    raise exception using message = 'cannot_change_owner', detail = 'The owner''s role cannot be changed', errcode = '42501';
  end if;
  if my_role = 'admin' and target_role <> 'member' then
    raise exception using message = 'not_allowed', detail = 'Admins can only manage regular members', errcode = '42501';
  end if;

  update public.group_members m
  set role = set_member_role.role
  where m.group_id = set_member_role.group_id and m.user_id = set_member_role.user_id;
end;
$$;


ALTER FUNCTION "public"."set_member_role"("group_id" "uuid", "user_id" "uuid", "role" "public"."group_role") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_notification_pref"("category" "text", "push" boolean DEFAULT NULL::boolean, "email" boolean DEFAULT NULL::boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  uid uuid := private.require_user();
begin
  if not exists (
    select 1 from private.notification_categories c where c.category = set_notification_pref.category
  ) then
    raise exception using message = 'invalid_notification_category', detail = 'Unknown notification setting', errcode = '22023';
  end if;

  insert into public.notification_prefs as p (user_id, category, push, email)
  values (uid, set_notification_pref.category, set_notification_pref.push, set_notification_pref.email)
  on conflict (user_id, category) do update
    set push = coalesce(excluded.push, p.push),
        email = coalesce(excluded.email, p.email);

  -- An email setting changed by hand makes any unsubscribe snapshot stale.
  if set_notification_pref.email is not null then
    delete from private.email_unsubscribe_undo u where u.user_id = uid;
  end if;
end;
$$;


ALTER FUNCTION "public"."set_notification_pref"("category" "text", "push" boolean, "email" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."settle_up"("group_id" "uuid", "to_user" "uuid", "amount_cents" bigint, "currency" "text" DEFAULT NULL::"text", "note" "text" DEFAULT NULL::"text") RETURNS "public"."settlements"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
#variable_conflict use_column
declare
  uid uuid := auth.uid();
  payer uuid := uid;
  g public.groups;
  cur text;
  fx numeric;
  result public.settlements;
begin
  perform 1 from public.groups x where x.id = settle_up.group_id for share;
  perform private.require_member(settle_up.group_id);
  perform private.require_unarchived(settle_up.group_id);
  select * into g from public.groups x where x.id = settle_up.group_id;

  if settle_up.amount_cents is null or settle_up.amount_cents <= 0 or settle_up.amount_cents > 100000000000 then
    raise exception using message = 'invalid_amount', detail = 'Enter an amount greater than zero', errcode = '22023';
  end if;
  if settle_up.to_user is null or settle_up.to_user = payer then
    raise exception using message = 'invalid_recipient', detail = 'Pick who you paid', errcode = '22023';
  end if;
  if (
    select count(*) from public.group_members m
    where m.group_id = settle_up.group_id and m.user_id in (payer, settle_up.to_user)
  ) <> 2 then
    raise exception using message = 'member_not_found', detail = 'Both people must be in the group', errcode = 'PT404';
  end if;

  cur := upper(coalesce(nullif(btrim(settle_up.currency), ''), g.currency));
  if cur !~ '^[A-Z]{3}$' then
    raise exception using message = 'invalid_currency', detail = 'Unknown currency code', errcode = '22023';
  end if;
  fx := private.fx_rate(cur::char(3), g.currency, current_date);
  if fx is null then
    raise exception using
      message = 'fx_rate_unavailable',
      detail = format('No exchange rate from %s to %s yet', cur, g.currency),
      errcode = '23514';
  end if;

  insert into public.settlements (group_id, from_user, to_user, amount_cents, currency, fx_rate, note, settled_at, created_by)
  values (
    settle_up.group_id, payer, settle_up.to_user, settle_up.amount_cents, cur, fx,
    nullif(btrim(settle_up.note), ''), now(), uid
  )
  returning * into result;

  return result;
end;
$_$;


ALTER FUNCTION "public"."settle_up"("group_id" "uuid", "to_user" "uuid", "amount_cents" bigint, "currency" "text", "note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."simplified_debts"("group_id" "uuid") RETURNS TABLE("from_user" "uuid", "to_user" "uuid", "amount_cents" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  creditors uuid[];
  credits bigint[];
  debtors uuid[];
  debts bigint[];
  ci int;
  di int;
  pay bigint;
begin
  perform private.require_member(simplified_debts.group_id);

  select
    coalesce(array_agg(b.user_id order by b.user_id) filter (where b.net_cents > 0), '{}'),
    coalesce(array_agg(b.net_cents order by b.user_id) filter (where b.net_cents > 0), '{}'),
    coalesce(array_agg(b.user_id order by b.user_id) filter (where b.net_cents < 0), '{}'),
    coalesce(array_agg(-b.net_cents order by b.user_id) filter (where b.net_cents < 0), '{}')
  into creditors, credits, debtors, debts
  from public.group_balances b
  where b.group_id = simplified_debts.group_id;

  loop
    -- Largest remaining creditor and debtor; arrays are in user id order, so
    -- strict > keeps the smallest id on ties.
    ci := null;
    for i in 1 .. coalesce(cardinality(credits), 0) loop
      if credits[i] > 0 and (ci is null or credits[i] > credits[ci]) then
        ci := i;
      end if;
    end loop;

    di := null;
    for i in 1 .. coalesce(cardinality(debts), 0) loop
      if debts[i] > 0 and (di is null or debts[i] > debts[di]) then
        di := i;
      end if;
    end loop;

    exit when ci is null or di is null;

    pay := least(credits[ci], debts[di]);
    credits[ci] := credits[ci] - pay;
    debts[di] := debts[di] - pay;

    from_user := debtors[di];
    to_user := creditors[ci];
    amount_cents := pay;
    return next;
  end loop;
end;
$$;


ALTER FUNCTION "public"."simplified_debts"("group_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."transfer_ownership"("group_id" "uuid", "user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  my_role public.group_role := private.require_member(transfer_ownership.group_id);
  uid uuid := auth.uid();
begin
  if my_role <> 'owner' then
    raise exception using message = 'not_allowed', detail = 'Only the owner can transfer ownership', errcode = '42501';
  end if;
  if transfer_ownership.user_id = uid then
    raise exception using message = 'already_owner', detail = 'You already own this group', errcode = '22023';
  end if;
  if not exists (
    select 1 from public.group_members m
    join public.profiles p on p.id = m.user_id
    where m.group_id = transfer_ownership.group_id
      and m.user_id = transfer_ownership.user_id
      and p.deleted_at is null
  ) then
    raise exception using message = 'member_not_found', detail = 'That person is not in this group', errcode = 'PT404';
  end if;

  -- Demote first: the one-owner unique index is not deferrable.
  update public.group_members m set role = 'admin'
  where m.group_id = transfer_ownership.group_id and m.user_id = uid;

  update public.group_members m set role = 'owner'
  where m.group_id = transfer_ownership.group_id and m.user_id = transfer_ownership.user_id;
end;
$$;


ALTER FUNCTION "public"."transfer_ownership"("group_id" "uuid", "user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_expense"("id" "uuid", "payload" "jsonb") RETURNS "public"."expenses"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if update_expense.id is null then
    raise exception using message = 'expense_not_found', detail = 'Expense not found', errcode = 'PT404';
  end if;
  return private.save_expense(
    update_expense.id,
    coalesce(payload, '{}'::jsonb) - array['payers', 'is_refund', 'items', 'tax_cents', 'tip_cents', 'discount_cents']
  );
end;
$$;


