CREATE OR REPLACE VIEW "public"."group_balances" WITH ("security_invoker"='true') AS
 WITH "expense_totals" AS NOT MATERIALIZED (
         SELECT "e"."id",
            "e"."group_id",
                CASE
                    WHEN "e"."is_refund" THEN '-1'::integer
                    ELSE 1
                END AS "sign",
            "private"."convert_minor"("e"."amount_cents", "e"."fx_rate", ("e"."currency")::"text", ("g"."currency")::"text") AS "total"
           FROM ("public"."expenses" "e"
             JOIN "public"."groups" "g" ON (("g"."id" = "e"."group_id")))
          WHERE ("e"."deleted_at" IS NULL)
        ), "split_parts" AS (
         SELECT "t"."id",
            "t"."group_id",
            "t"."total",
            "t"."sign",
            "s"."user_id",
            "div"((("t"."total")::numeric * ("s"."share_cents")::numeric), "sum"("s"."share_cents") OVER "w") AS "base",
            "mod"((("t"."total")::numeric * ("s"."share_cents")::numeric), "sum"("s"."share_cents") OVER "w") AS "rem"
           FROM ("expense_totals" "t"
             JOIN "public"."expense_splits" "s" ON (("s"."expense_id" = "t"."id")))
          WINDOW "w" AS (PARTITION BY "t"."group_id", "t"."id")
        ), "split_shares" AS (
         SELECT "p"."group_id",
            "p"."user_id",
            "p"."sign",
            ("p"."base" + (
                CASE
                    WHEN (("row_number"() OVER (PARTITION BY "p"."group_id", "p"."id" ORDER BY "p"."rem" DESC, "p"."user_id"))::numeric <= (("p"."total")::numeric - "sum"("p"."base") OVER (PARTITION BY "p"."group_id", "p"."id"))) THEN 1
                    ELSE 0
                END)::numeric) AS "share"
           FROM "split_parts" "p"
        ), "payer_parts" AS (
         SELECT "t"."id",
            "t"."group_id",
            "t"."total",
            "t"."sign",
            "x"."user_id",
            "div"((("t"."total")::numeric * ("x"."paid_cents")::numeric), "sum"("x"."paid_cents") OVER "w") AS "base",
            "mod"((("t"."total")::numeric * ("x"."paid_cents")::numeric), "sum"("x"."paid_cents") OVER "w") AS "rem"
           FROM ("expense_totals" "t"
             JOIN "public"."expense_payers" "x" ON (("x"."expense_id" = "t"."id")))
          WINDOW "w" AS (PARTITION BY "t"."group_id", "t"."id")
        ), "payer_shares" AS (
         SELECT "p"."group_id",
            "p"."user_id",
            "p"."sign",
            ("p"."base" + (
                CASE
                    WHEN (("row_number"() OVER (PARTITION BY "p"."group_id", "p"."id" ORDER BY "p"."rem" DESC, "p"."user_id"))::numeric <= (("p"."total")::numeric - "sum"("p"."base") OVER (PARTITION BY "p"."group_id", "p"."id"))) THEN 1
                    ELSE 0
                END)::numeric) AS "share"
           FROM "payer_parts" "p"
        ), "ledger" AS (
         SELECT "m"."group_id",
            "m"."user_id",
            (0)::numeric AS "delta"
           FROM "public"."group_members" "m"
        UNION ALL
         SELECT "x"."group_id",
            "x"."user_id",
            (("x"."sign")::numeric * "x"."share")
           FROM "payer_shares" "x"
        UNION ALL
         SELECT "s"."group_id",
            "s"."user_id",
            (((- "s"."sign"))::numeric * "s"."share")
           FROM "split_shares" "s"
        UNION ALL
         SELECT "st"."group_id",
            "st"."from_user",
            ("private"."convert_minor"("st"."amount_cents", "st"."fx_rate", ("st"."currency")::"text", ("g"."currency")::"text"))::numeric AS "convert_minor"
           FROM ("public"."settlements" "st"
             JOIN "public"."groups" "g" ON (("g"."id" = "st"."group_id")))
          WHERE ("st"."deleted_at" IS NULL)
        UNION ALL
         SELECT "st"."group_id",
            "st"."to_user",
            (- ("private"."convert_minor"("st"."amount_cents", "st"."fx_rate", ("st"."currency")::"text", ("g"."currency")::"text"))::numeric)
           FROM ("public"."settlements" "st"
             JOIN "public"."groups" "g" ON (("g"."id" = "st"."group_id")))
          WHERE ("st"."deleted_at" IS NULL)
        )
 SELECT "group_id",
    "user_id",
    ("sum"("delta"))::bigint AS "net_cents"
   FROM "ledger" "l"
  GROUP BY "group_id", "user_id";


