    CONSTRAINT "profiles_default_currency_check" CHECK (("default_currency" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "profiles_display_name_check" CHECK ((("char_length"("btrim"("display_name")) >= 1) AND ("char_length"("btrim"("display_name")) <= 80)))
);


ALTER TABLE "public"."profiles" OWNER TO "postgres";


COMMENT ON TABLE "public"."profiles" IS 'One row per auth user. Tombstoned (not deleted) when an account is closed.';



CREATE TABLE IF NOT EXISTS "public"."push_tokens" (
    "user_id" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "token" "text" NOT NULL,
    "platform" "public"."push_platform" NOT NULL,
    "subscription" "jsonb",
    "last_seen_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "push_tokens_token_check" CHECK (("char_length"("token") <= 2048))
);


ALTER TABLE "public"."push_tokens" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."reports" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "reporter_id" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "subject_user_id" "uuid",
    "group_id" "uuid",
    "reason" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "reports_check" CHECK ((("subject_user_id" IS NOT NULL) OR ("group_id" IS NOT NULL))),
    CONSTRAINT "reports_reason_check" CHECK ((("char_length"("btrim"("reason")) >= 1) AND ("char_length"("btrim"("reason")) <= 2000)))
);


ALTER TABLE "public"."reports" OWNER TO "postgres";


